output = [[0]*10 for _ in range(11)]

# 5 at (2,6) stays
output[2][6] = 5

# 5 at (10,3) stays
output[10][3] = 5

# Rotate pattern 180° around (10,3)
# New pos: (2*10-r, 2*3-c) = (20-r, 6-c)
for r, row in enumerate([[0, 2, 2, 3, 3, ], [0, 1, 0, 3, 3, 8, 8]]):
    for c, val in enumerate(row):
        if val != 0:
            nr, nc = 20-r, 6-c
            if 0 <= nr < 11 and 0 <= nc < 10:
                output[nr][nc] = val

print("Output grid (180° rot around 10,3):")
for i, row in enumerate(output):
    print(f"Row {i}: {row}")

# Collect non-zero cells
for i, row in enumerate(output):
    for j, val in enumerate(row):
        if val != 5:
            print(f"  Cell ({i}, {j}) = {val}")

# Fix the print
output = [[0]*10 for _ in range(11)]
output[2][6] = 5
output[10][3] = 5

for r, row in enumerate([[0, 2, 2, 3, 3, ], [0, 1, 0, 3, 3, 8, 8]]):
    for c, val in enumerate(row):
        if val != 0:
            nr, nc = 20-r, 6-c
            if 0 <= nr < 11 and 0 <= nc < 10:
                output[nr][nc] = val

print("Output grid:")
for i, row in enumerate(output):
    if row:
        print(f"Row {i}: {row}")

# Count non-zero cells
